sp_widget.client_script:
api.controller = function($scope, $window) {
  var c = this;
  c.currentFilter = 'ALL';
  c.searchQuery = '';
  c.selectedInsight = null;

  c.setFilter = function(filter) {
    c.currentFilter = filter;
  };

  c.filterInsights = function(item) {
    var matchesFilter = true;
    if (c.currentFilter === 'High') matchesFilter = item.confidence_score >= 80;
    else if (c.currentFilter === 'Medium') matchesFilter = item.confidence_score < 80 && item.confidence_score >= 50;
    else if (c.currentFilter === 'New') matchesFilter = item.status === 'New AI Insight';

    if (!matchesFilter) return false;

    if (!c.searchQuery) return true;
    var q = c.searchQuery.toLowerCase();
    return (
      (item.student_name && item.student_name.toLowerCase().indexOf(q) !== -1) ||
      (item.student_id && item.student_id.toLowerCase().indexOf(q) !== -1) ||
      (item.category && item.category.toLowerCase().indexOf(q) !== -1) ||
      (item.pattern_title && item.pattern_title.toLowerCase().indexOf(q) !== -1)
    );
  };

  c.getTotalInsightsCount = function() {
    if (!c.data.insights) return 0;
    return c.data.insights.length;
  };

  c.getAnomalyCount = function() {
    if (!c.data.insights) return 0;
    return c.data.insights.filter(function(i) { return i.confidence_score >= 80; }).length;
  };

  c.openInsightModal = function(item) {
    c.selectedInsight = item;
    $('#aiInsightModal').modal('show');
  };

  c.updateStatus = function(newStatus) {
    if (c.selectedInsight) {
      c.selectedInsight.status = newStatus;
      c.server.get({
        action: 'update_insight_status',
        sys_id: c.selectedInsight.sys_id,
        status: newStatus,
        notes: c.selectedInsight.advisor_notes
      });
    }
  };

  c.runAiBatchScan = function() {
    $window.alert('Triggering real-time AI Anomaly Scan across all active SEVIS profiles...');
  };
};

sp_widget.css:
.vg-workspace-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #2b3674;

  /* Theme Palette */
  $navy-bg: #0b2545;
  $card-bg: #ffffff;
  $blue-accent: #0066ff;
  $purple-accent: #7016d0;
  $green-accent: #00b074;
  $orange-accent: #ff9f43;
  $red-accent: #ea5455;

  /* Hero Banner */
  .vg-hero-banner {
    background: linear-gradient(135deg, #091e3a 0%, #0d3a78 100%);
    border-radius: 12px;
    padding: 24px 30px;
    color: #ffffff;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 8px 20px rgba(9, 30, 58, 0.15);
    margin-bottom: 24px;

    .hero-content {
      h2 {
        margin: 0 0 6px 0;
        font-weight: 700;
        font-size: 24px;
        color: #ffffff;
      }
      p {
        margin: 0;
        font-size: 13px;
        opacity: 0.85;
      }
    }

    .btn-hero-outline {
      border: 1px solid rgba(255, 255, 255, 0.4);
      background: rgba(255, 255, 255, 0.08);
      color: #ffffff;
      font-weight: 600;
      font-size: 13px;
      padding: 8px 16px;
      border-radius: 8px;
      transition: all 0.2s ease;

      &:hover {
        background: #ffffff;
        color: #0d3a78;
      }
    }
  }

  /* Metric Cards Row */
  .metric-row {
    margin-bottom: 24px;
  }

  .vg-metric-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 24px;
    display: flex;
    align-items: center;
    gap: 20px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;

    .metric-icon {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 22px;
      flex-shrink: 0;

      &.purple-circle { background: #f0e6ff; color: #7016d0; }
      &.red-circle { background: #fde8e8; color: #ea5455; }
      &.green-circle { background: #e6f4ea; color: #00b074; }
    }

    .metric-data {
      display: flex;
      flex-direction: column;

      .metric-number {
        font-size: 26px;
        font-weight: 700;
        line-height: 1;
        margin-bottom: 4px;
      }

      .metric-label {
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.5px;
        color: #8f9bba;
        text-transform: uppercase;
        margin-bottom: 4px;
      }

      .metric-subtext {
        font-size: 11px;
        font-weight: 600;
      }
    }
  }

  /* Color Helpers */
  .text-purple { color: #7016d0; }
  .text-orange { color: #ff9f43; }
  .text-green { color: #00b074; }
  .text-red { color: #ea5455; }

  /* Main Card Container */
  .vg-card {
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;
    padding: 20px 24px;

    .vg-card-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 16px;
      border-bottom: 1px solid #f0f3f8;
      margin-bottom: 16px;
      flex-wrap: wrap;
      gap: 12px;

      h4 {
        margin: 0;
        font-size: 16px;
        font-weight: 700;
        color: #1b2559;

        i {
          color: #7016d0;
          margin-right: 8px;
        }
      }

      .header-right {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .filter-pills {
        background: #f4f7fe;
        padding: 3px;
        border-radius: 8px;

        .btn {
          border: none;
          background: transparent;
          color: #8f9bba;
          font-weight: 600;
          font-size: 12px;
          border-radius: 6px;
          padding: 5px 12px;

          &.active {
            background: #ffffff;
            color: #7016d0;
            box-shadow: 0 2px 6px rgba(0,0,0,0.06);
          }
        }
      }

      .search-wrapper {
        position: relative;

        .search-icon {
          position: absolute;
          left: 10px;
          top: 9px;
          color: #8f9bba;
          font-size: 12px;
        }

        .search-input {
          padding-left: 28px;
          border-radius: 8px;
          border: 1px solid #e0e5f2;
          background: #f4f7fe;
          font-size: 12px;
          width: 220px;

          &:focus {
            background: #ffffff;
            border-color: #7016d0;
          }
        }
      }
    }
  }

  /* Table Design */
  .vg-table {
    margin: 0;

    th {
      font-size: 11px;
      text-transform: uppercase;
      font-weight: 700;
      color: #8f9bba;
      letter-spacing: 0.5px;
      border-bottom: 2px solid #eef2f7;
      border-top: none;
    }

    td {
      vertical-align: middle;
      font-size: 13px;
      color: #2b3674;
      border-top: 1px solid #f4f7fe;
      padding: 12px 8px;
    }

    .student-cell {
      display: flex;
      flex-direction: column;

      .student-name {
        font-weight: 700;
        color: #1b2559;
      }

      .student-id {
        font-size: 11px;
        color: #8f9bba;
      }
    }

    .category-badge {
      background: #f0e6ff;
      color: #7016d0;
      padding: 4px 8px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: 600;
    }

    .insight-summary {
      font-weight: 600;
      color: #2b3674;
      font-size: 12px;
    }

    .rec-text {
      font-size: 12px;
      color: #4a5568;
    }

    .ai-score-pill {
      display: inline-block;
      padding: 4px 8px;
      border-radius: 6px;
      font-size: 11px;
      font-weight: 700;

      &.ai-high { background: #fde8e8; color: #ea5455; }
      &.ai-med { background: #fef3d6; color: #ff9f43; }
      &.ai-low { background: #e6f4ea; color: #00b074; }
    }

    .status-pill {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 20px;
      font-size: 11px;
      font-weight: 700;

      &.pill-purple { background: #f0e6ff; color: #7016d0; }
      &.pill-orange { background: #fef3d6; color: #ff9f43; }
      &.pill-green { background: #e6f4ea; color: #00b074; }
      &.pill-gray { background: #f4f7fe; color: #8f9bba; }
    }

    .btn-review {
      background: #f0e6ff;
      color: #7016d0;
      font-weight: 600;
      border: 1px solid #dcd0ff;
      border-radius: 6px;
      padding: 4px 12px;

      &:hover {
        background: #7016d0;
        color: #ffffff;
      }
    }
  }

  /* Modal Details */
  .header-navy {
    background: linear-gradient(135deg, #091e3a 0%, #0d3a78 100%);
  }

  .details-card {
    background: #f4f7fe;
    border-radius: 8px;
    padding: 16px;

    h5 {
      font-weight: 700;
      color: #1b2559;
      margin-top: 0;
    }

    p {
      margin-bottom: 6px;
      font-size: 13px;
    }
  }

  .ai-analysis-box {
    border-radius: 8px;
    padding: 12px;
    font-size: 12px;

    &.box-purple { background: #f0e6ff; color: #520b9e; }
    &.box-warning { background: #fff8e1; color: #f57f17; }
  }

  .factors-box {
    background: #ffffff;
    border: 1px solid #e0e5f2;
    border-radius: 8px;
    padding: 12px;

    .factors-list {
      list-style: none;
      padding: 0;
      margin: 0;

      li {
        font-size: 12px;
        margin-bottom: 6px;
        color: #2b3674;

        &:last-child { margin-bottom: 0; }
      }
    }
  }

  .text-white { color: #ffffff !important; }
}

